/// @sort 32
uniform float Alpha = 0.5;
// A ShaderLayerBlend: its material inputs in order, then the result.
/// @name Layers/MLB_LpOverlay
/// @layerblend
export void MLB_LpOverlay(material Bottom, material Top, inout material Attrs)
{
    Attrs.BaseColor = lerp(Bottom.BaseColor, Top.BaseColor, Alpha);
}
